<?php $title='Integraciones'; require __DIR__.'/partials/top.php';$rows=[];$keys=[];$env=envConfig($root.'/.env');$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=$_SERVER['HTTP_HOST']??'localhost';$publishedBase='';try{$sq=appDb()->prepare("SELECT setting_value FROM system_settings WHERE setting_key='seo_site_url' LIMIT 1");$sq->execute();$publishedBase=trim((string)($sq->fetchColumn()?:''));}catch(Throwable $e){}if($publishedBase==='')$publishedBase=trim((string)($env['APP_URL']??''));if($publishedBase==='')$publishedBase=$scheme.'://'.$host.rtrim(dirname($_SERVER['SCRIPT_NAME']??'/'),'/');$publishedBase=htmlspecialchars_decode($publishedBase,ENT_QUOTES);$publishedBase=str_replace('\\','',$publishedBase);$publishedBase=trim($publishedBase);if($publishedBase!==''&&!preg_match('~^https?://~i',$publishedBase))$publishedBase=$scheme.'://'.ltrim($publishedBase,'/');$publishedBase=rtrim($publishedBase,'/');$apiRoot=$publishedBase.'/api.php?r=';try{require_once dirname(__DIR__).'/Support/AccessPolicy.php';ZynkoAccessPolicy::ensureTables(appDb());}catch(Throwable $e){}try{$q=appDb()->prepare('SELECT id,name,url,events_json,active,created_at FROM outgoing_webhooks WHERE tenant_id=? ORDER BY id DESC');$q->execute([$_SESSION['user']['tenant_id']]);$rows=$q->fetchAll();$q=appDb()->prepare('SELECT k.id,k.name,k.key_prefix,k.last_used_at,k.created_at,k.revoked_at,k.expires_at,k.scopes_json,p.allowed_origins_json,p.allowed_ips_json,p.rate_limit_per_minute,p.require_https,p.active policy_active FROM api_keys k LEFT JOIN api_client_policies p ON p.api_key_id=k.id WHERE k.tenant_id=? ORDER BY k.id DESC');$q->execute([$_SESSION['user']['tenant_id']]);$keys=$q->fetchAll();}catch(Throwable $e){} ?>
<section class="welcome"><div><small>API & WEBHOOKS</small><h1>Integraciones</h1><p>Conecta IZZY, CAMI u otros sistemas mediante webhooks HTTPS firmados.</p></div><button class="primary" data-open="integrationModal"><i class="fa-solid fa-plug-circle-plus"></i> Nueva integración</button></section><section class="panel"><div class="card-list"><?php if(!$rows):?><div class="empty-compact"><i class="fa-solid fa-plug"></i><b>Aún no hay integraciones</b><span>Crea la primera para empezar a intercambiar eventos.</span></div><?php else:foreach($rows as $r):?><article class="integration-card"><span class="channel-icon"><i class="fa-solid fa-webhook"></i></span><div><b><?=htmlspecialchars($r['name'])?></b><small><?=htmlspecialchars($r['url'])?></small></div><span class="ui-badge <?=$r['active']?'success':'muted'?>"><i class="fa-solid fa-circle"></i><?=$r['active']?'Activa':'Inactiva'?></span></article><?php endforeach;endif?></div></section>
<section class="panel"><div class="panel-head premium-card-head"><span class="premium-card-head-icon" aria-hidden="true"><i class="fa-solid fa-plug"></i></span><div><b>Acceso API para IZZY, CAMI y otros sistemas</b><small>Solo sistemas con una clave secreta válida pueden enviar solicitudes a ZYNKO.</small></div><button class="primary" data-open="apiKeyModal"><i class="fa-solid fa-key"></i> Crear clave API</button></div><div class="api-key-list"><?php if(!$keys):?><div class="empty-compact"><i class="fa-solid fa-shield-halved"></i><b>No hay claves API</b><span>Crea una clave distinta por cada sistema externo.</span></div><?php else:foreach($keys as $k):$origins=json_decode((string)($k['allowed_origins_json']??'[]'),true)?:[];$ips=json_decode((string)($k['allowed_ips_json']??'[]'),true)?:[];$scopes=json_decode((string)($k['scopes_json']??'[]'),true)?:[];?><article class="api-key-row"><div><b><?=htmlspecialchars($k['name'])?></b><small><?=htmlspecialchars($k['key_prefix'])?>•••••••• · <?= $k['last_used_at']?'Último uso '.$k['last_used_at']:'Nunca utilizada'?></small><div class="api-policy-summary"><span><i class="fa-solid fa-globe"></i> <?=$origins?count($origins).' origen(es)':'Cualquier origen con clave válida'?></span><span><i class="fa-solid fa-network-wired"></i> <?=$ips?count($ips).' IP/CIDR':'Cualquier IP'?></span><span><i class="fa-solid fa-gauge-high"></i> <?=max(10,(int)($k['rate_limit_per_minute']??120))?>/min</span><span><i class="fa-solid fa-key"></i> <?=count($scopes)?> permisos</span></div></div><span class="ui-badge <?=$k['revoked_at']?'danger':'success'?>"><i class="fa-solid fa-circle"></i><?=$k['revoked_at']?'Revocada':'Activa'?></span><?php if(!$k['revoked_at']):?><button type="button" class="soft api-policy-edit" data-id="<?=$k['id']?>" data-name="<?=htmlspecialchars($k['name'],ENT_QUOTES)?>" data-origins="<?=htmlspecialchars(implode("
",$origins),ENT_QUOTES)?>" data-ips="<?=htmlspecialchars(implode("
",$ips),ENT_QUOTES)?>" data-rate="<?=max(10,(int)($k['rate_limit_per_minute']??120))?>" data-https="<?=!array_key_exists('require_https',$k)||!empty($k['require_https'])?'1':'0'?>" data-active="<?=!array_key_exists('policy_active',$k)||$k['policy_active']===null||!empty($k['policy_active'])?'1':'0'?>"><i class="fa-solid fa-shield-halved"></i> Permisos</button><button class="soft danger api-key-revoke" data-id="<?=$k['id']?>"><i class="fa-solid fa-ban"></i> Revocar</button><?php endif?></article><?php endforeach;endif?></div><div class="api-doc"><i class="fa-solid fa-code"></i><div><b>API REST segura</b><small>Endpoint local: <code>/api.php?r=v1/messages/send</code>. Usa <code>Authorization: Bearer TU_CLAVE</code> e <code>Idempotency-Key</code> para evitar duplicados. ZYNKO rechaza claves inválidas, revocadas o sin permisos.</small></div></div></section>
<section class="panel nivo-install-doc-panel"><div class="panel-head premium-card-head"><span class="premium-card-head-icon" aria-hidden="true"><i class="fa-solid fa-plug"></i></span><div><b><i class="fa-solid fa-robot"></i> Configurar e instalar NIVO Web Chat</b><small>NIVO Web Chat no necesita una clave API para instalarse. Cada dominio externo usa su propio código de instalación.</small></div><a class="primary" href="?page=webchat"><i class="fa-solid fa-message"></i> Abrir NIVO Web Chat</a></div><div class="nivo-install-doc-grid"><article><span>1</span><div><b>Configura NIVO IA</b><small>Define reglas, conocimiento aprobado y transferencia humana desde NIVO · IA.</small></div></article><article><span>2</span><div><b>Personaliza el widget</b><small>Ajusta saludo, posición, privacidad, respuestas rápidas y experiencia desde NIVO Web Chat.</small></div></article><article><span>3</span><div><b>Autoriza el dominio</b><small>Agrega el sitio externo. El máximo permitido depende del plan de la empresa.</small></div></article><article><span>4</span><div><b>Copia el script único</b><small>La tarjeta del sitio muestra el código exclusivo. Pégalo antes de &lt;/body&gt; y verifica “Último uso”.</small></div></article></div><div class="nivo-install-doc-note"><i class="fa-solid fa-shield-halved"></i><span>El sitio principal de ZYNKO se administra automáticamente y no consume el cupo de sitios externos. Las claves API de esta página son para integrar sistemas; no son necesarias para instalar NIVO Web Chat.</span></div><div class="nivo-install-doc-note"><i class="fa-solid fa-building-shield"></i><span><b>Multiempresa real:</b> NIVO Web Chat resuelve el tenant desde la instalación autorizada. NIVO IA consulta reglas, conocimiento, fuentes web y aprendizaje únicamente de esa empresa. Las fuentes de una empresa nunca se comparten automáticamente con otra.</span></div></section>
<section class="panel api-howto-panel"><div class="panel-head premium-card-head"><span class="premium-card-head-icon" aria-hidden="true"><i class="fa-solid fa-plug"></i></span><div><b>Cómo usar ZYNKO desde otro sistema</b><small>La URL se toma automáticamente del sitio publicado. No necesitas editar el dominio de los ejemplos manualmente.</small></div><span class="status-badge connected"><i class="fa-solid fa-link"></i> <?=htmlspecialchars(preg_replace('~/api\.php\?r=$~','',$apiRoot))?></span></div><div class="security-note"><i class="fa-solid fa-shield-halved"></i><div><b>Política de seguridad por clave</b><small>Antes de integrar, define los scopes mínimos y, si aplica, limita la credencial por origen web, IP/CIDR, HTTPS, vencimiento y rate limit. Estas reglas se validan en servidor y pueden editarse sin regenerar la clave.</small></div></div><div class="api-flow-grid"><article class="api-flow-card"><span>1</span><div><b>Crear clave API</b><small>Ve a <strong>Integraciones → Crear clave API</strong>. La llave pertenece únicamente a esta empresa.</small></div></article><article class="api-flow-card"><span>2</span><div><b>Consultar canales</b><code>GET <?=htmlspecialchars($apiRoot)?>v1/channels</code><small>Obtén el channel_id de WhatsApp, Messenger, NIVO Web Chat y demás canales habilitados.</small></div></article><article class="api-flow-card"><span>3</span><div><b>Recibir hacia NIVO</b><code>POST <?=htmlspecialchars($apiRoot)?>v1/messages/receive</code><small>Registra la conversación, ejecuta NIVO IA y devuelve respuesta o handoff.</small></div></article><article class="api-flow-card"><span>4</span><div><b>Enviar mensaje</b><code>POST <?=htmlspecialchars($apiRoot)?>v1/messages/send</code><small>Valida el canal, registra el mensaje saliente y lo deja en cola para el despachador del conector autorizado.</small></div></article></div>
