document.addEventListener('DOMContentLoaded',()=>{
  const modal=document.getElementById('apiPolicyModal'),form=document.getElementById('apiPolicyForm');
  document.querySelectorAll('.api-policy-edit').forEach(btn=>btn.addEventListener('click',()=>{
    if(!modal||!form)return;
    form.api_key_id.value=btn.dataset.id||'0';form.allowed_origins.value=btn.dataset.origins||'';form.allowed_ips.value=btn.dataset.ips||'';form.rate_limit_per_minute.value=btn.dataset.rate||'120';form.require_https.checked=btn.dataset.https==='1';form.active.checked=btn.dataset.active==='1';
    const name=document.getElementById('apiPolicyName');if(name)name.textContent='Clave: '+(btn.dataset.name||'API');modal.classList.add('open');
  }));
});
</script>
